import pytest
from pricing.summary import summarize

def test_empty_quotes():
    assert summarize([]) == {"basic": 0.0, "plus": 0.0, "pro": 0.0, "grand_total": 0.0}

def test_single_basic_quote():
    quotes = [{"tier": "basic", "rate": 10.0, "subtotal": 10.0, "total": 10.0}]
    assert summarize(quotes) == {"basic": 10.0, "plus": 0.0, "pro": 0.0, "grand_total": 10.0}

def test_single_plus_quote():
    quotes = [{"tier": "plus", "rate": 15.5, "subtotal": 15.5, "total": 15.5}]
    assert summarize(quotes) == {"basic": 0.0, "plus": 15.5, "pro": 0.0, "grand_total": 15.5}

def test_single_pro_quote():
    quotes = [{"tier": "pro", "rate": 20.0, "subtotal": 20.0, "total": 20.25}]
    assert summarize(quotes) == {"basic": 0.0, "plus": 0.0, "pro": 20.25, "grand_total": 20.25}

def test_mixed_quotes():
    quotes = [
        {"tier": "basic", "rate": 10.0, "subtotal": 10.0, "total": 10.5},
        {"tier": "pro", "rate": 20.0, "subtotal": 20.0, "total": 20.25},
        {"tier": "basic", "rate": 10.0, "subtotal": 10.0, "total": 5.25},
    ]
    assert summarize(quotes) == {"basic": 15.75, "plus": 0.0, "pro": 20.25, "grand_total": 36.0}

def test_floating_point_noise_cleared():
    quotes = [
        {"tier": "basic", "rate": 0.1, "subtotal": 0.1, "total": 0.1},
        {"tier": "basic", "rate": 0.2, "subtotal": 0.2, "total": 0.2},
    ]
    assert summarize(quotes) == {"basic": 0.3, "plus": 0.0, "pro": 0.0, "grand_total": 0.3}

def test_round_half_to_even_down():
    quotes = [{"tier": "basic", "rate": 1.0, "subtotal": 1.0, "total": 0.125}]
    assert summarize(quotes) == {"basic": 0.12, "plus": 0.0, "pro": 0.0, "grand_total": 0.12}

def test_round_half_to_even_up():
    quotes = [{"tier": "plus", "rate": 1.0, "subtotal": 1.0, "total": 0.375}]
    assert summarize(quotes) == {"basic": 0.0, "plus": 0.38, "pro": 0.0, "grand_total": 0.38}

def test_binary_float_representation_rounding():
    quotes = [{"tier": "pro", "rate": 1.0, "subtotal": 1.0, "total": 2.675}]
    assert summarize(quotes) == {"basic": 0.0, "plus": 0.0, "pro": 2.67, "grand_total": 2.67}

def test_grand_total_summed_from_raw_totals():
    quotes = [
        {"tier": "basic", "rate": 1.0, "subtotal": 1.0, "total": 0.004},
        {"tier": "plus", "rate": 1.0, "subtotal": 1.0, "total": 0.004},
    ]
    assert summarize(quotes) == {"basic": 0.0, "plus": 0.0, "pro": 0.0, "grand_total": 0.01}

def test_input_mutation_prevented():
    q1 = {"tier": "basic", "rate": 5.0, "subtotal": 5.0, "total": 5.0}
    quotes = [q1]
    summarize(quotes)
    assert quotes == [{"tier": "basic", "rate": 5.0, "subtotal": 5.0, "total": 5.0}]

def test_invalid_tier_raises_value_error():
    quotes = [{"tier": "enterprise", "rate": 50.0, "subtotal": 50.0, "total": 50.0}]
    with pytest.raises(ValueError):
        summarize(quotes)
